eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   UNAM_GEOGRAFIA_TOPICS: () => (/* binding */ UNAM_GEOGRAFIA_TOPICS)\n/* harmony export */ });\n/** Temario ultra-detallado de Geografía — Examen UNAM. */ const UNAM_GEOGRAFIA_TOPICS = [\n    {\n        \"id\": \"geo-ciencia\",\n        \"codigo\": \"1\",\n        \"titulo\": \"La Geograf\\xeda como Ciencia\",\n        \"orden\": 1,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"geo-ciencia-1-1\",\n                \"codigo\": \"1.1\",\n                \"titulo\": \"Metodolog\\xeda y Conceptos Espaciales\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-ciencia-1-1-1\",\n                        \"codigo\": \"1.1.1\",\n                        \"titulo\": \"Definici\\xf3n moderna\",\n                        \"descripcion\": \"La geograf\\xeda como ciencia interdependiente que estudia las interrelaciones entre los factores f\\xedsicos, biol\\xf3gicos y humanos que ocurren en la superficie terrestre.\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-ciencia-1-1-2\",\n                        \"codigo\": \"1.1.2\",\n                        \"titulo\": \"Hechos y Fen\\xf3menos Geogr\\xe1ficos\",\n                        \"descripcion\": \"Hechos: acontecimientos de larga duraci\\xf3n que transcurren lentamente (formaci\\xf3n de una cordillera, deriva continental, un oc\\xe9ano). Fen\\xf3menos: acontecimientos dr\\xe1sticos, r\\xe1pidos y de corta duraci\\xf3n (sismo, erupci\\xf3n volc\\xe1nica, hurac\\xe1n).\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-ciencia-1-1-3\",\n                        \"codigo\": \"1.1.3\",\n                        \"titulo\": \"Principios Metodol\\xf3gicos de Emmanuel de Martonne\",\n                        \"descripcion\": \"Localizaci\\xf3n/extensi\\xf3n: ubicaci\\xf3n exacta en el espacio geogr\\xe1fico. Causalidad: causas primarias del acontecimiento. Relaci\\xf3n/conexi\\xf3n: interacci\\xf3n con otros elementos del entorno. Evoluci\\xf3n/dinamismo: transformaciones a lo largo del tiempo.\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"geo-ciencia-1-2\",\n                \"codigo\": \"1.2\",\n                \"titulo\": \"Cartograf\\xeda y Coordenadas Geogr\\xe1ficas\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-ciencia-1-2-1\",\n                        \"codigo\": \"1.2.1\",\n                        \"titulo\": \"Puntos, l\\xedneas y c\\xedrculos imaginarios\",\n                        \"descripcion\": \"Eje terrestre (inclinaci\\xf3n 23\\xb027′), polos, Ecuador (hemisferio norte/boreal y sur/austral), tr\\xf3picos de C\\xe1ncer y Capricornio, c\\xedrculos polares \\xe1rtico y ant\\xe1rtico. Meridianos: Greenwich (meridiano cero) divide hemisferio este y oeste.\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-ciencia-1-2-2\",\n                        \"codigo\": \"1.2.2\",\n                        \"titulo\": \"Coordenadas Geogr\\xe1ficas\",\n                        \"descripcion\": \"Latitud: distancia angular respecto al Ecuador (0\\xb0 a 90\\xb0 N o S); zonas t\\xe9rmicas. Longitud: distancia angular respecto a Greenwich (0\\xb0 a 180\\xb0 E u O); husos horarios. Altitud: metros sobre el nivel del mar (msnm).\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-ciencia-1-2-3\",\n                        \"codigo\": \"1.2.3\",\n                        \"titulo\": \"Husos Horarios (c\\xe1lculo UNAM)\",\n                        \"descripcion\": \"La Tierra gira 360\\xb0 en 24 h → 15\\xb0 por huso (360/24 = 15); 24 husos en total. Regla: hacia el este se suman horas (+); hacia el oeste se restan (−). Conocer los husos horarios oficiales de M\\xe9xico.\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-ciencia-1-2-4\",\n                        \"codigo\": \"1.2.4\",\n                        \"titulo\": \"Proyecciones Cartogr\\xe1ficas\",\n                        \"descripcion\": \"Cil\\xedndrica (Mercator: navegaci\\xf3n, deforma polos), c\\xf3nica (latitudes medias y pa\\xedses templados), azimutal/cenital (zonas polares).\",\n                        \"orden\": 4,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        \"id\": \"geo-fisica\",\n        \"codigo\": \"2\",\n        \"titulo\": \"Geograf\\xeda F\\xedsica: El Paisaje Natural\",\n        \"orden\": 2,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"geo-fisica-2-1\",\n                \"codigo\": \"2.1\",\n                \"titulo\": \"Litosfera y Din\\xe1mica Interna de la Tierra\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-fisica-2-1-1\",\n                        \"codigo\": \"2.1.1\",\n                        \"titulo\": \"Estructura interna del planeta\",\n                        \"descripcion\": \"N\\xfacleo (interno s\\xf3lido y externo l\\xedquido, NiFe), manto (inferior y superior/astenosfera), corteza o litosfera (continental de granito/sial y oce\\xe1nica de basalto/sima).\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-1-2\",\n                        \"codigo\": \"2.1.2\",\n                        \"titulo\": \"Tect\\xf3nica de Placas y Deriva Continental\",\n                        \"descripcion\": \"Teor\\xeda de Alfred Wegener: supercontinente Pangea. Corrientes de convecci\\xf3n del manto que mueven las placas.\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-1-3\",\n                        \"codigo\": \"2.1.3\",\n                        \"titulo\": \"L\\xedmites de placas tect\\xf3nicas\",\n                        \"descripcion\": \"Divergentes: placas se separan, magma crea nueva corteza (Dorsal Mesoatl\\xe1ntica). Convergentes: subducci\\xf3n (Placa de Cocos bajo Norteamericana) o colisi\\xf3n continental (Himalaya). Transformantes: deslizamiento lateral (Falla de San Andr\\xe9s).\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-1-4\",\n                        \"codigo\": \"2.1.4\",\n                        \"titulo\": \"Sismicidad y Vulcanismo\",\n                        \"descripcion\": \"Foco/hipocentro y epicentro/ep\\xedfoco. Escalas Richter (magnitud) y Mercalli (intensidad). Cintur\\xf3n de Fuego del Pac\\xedfico. M\\xe9xico: Zona A (as\\xedsmica, Yucat\\xe1n, norte), B y C (penis\\xedsmica), D (altamente s\\xedsmica: costa del Pac\\xedfico central y sur por placas de Cocos y Rivera).\",\n                        \"orden\": 4,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"geo-fisica-2-2\",\n                \"codigo\": \"2.2\",\n                \"titulo\": \"Relieve, Intemperismo y Erosi\\xf3n\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-fisica-2-2-1\",\n                        \"codigo\": \"2.2.1\",\n                        \"titulo\": \"Formas del relieve\",\n                        \"descripcion\": \"Llanuras o planicies (baja altitud, agricultura y asentamientos), mesetas o altiplanicies (m\\xe1s de 500 msnm, ej. Meseta Central de M\\xe9xico), monta\\xf1as/cordilleras.\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-2-2\",\n                        \"codigo\": \"2.2.2\",\n                        \"titulo\": \"Modelado del relieve\",\n                        \"descripcion\": \"Intemperismo: degradaci\\xf3n de rocas in situ (temperatura, agua). Erosi\\xf3n: desgaste con acarreo y dep\\xf3sito por viento (e\\xf3lica), r\\xedos (fluvial), lluvia (pluvial) u oc\\xe9anos (marina).\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"geo-fisica-2-3\",\n                \"codigo\": \"2.3\",\n                \"titulo\": \"Hidrosfera: Aguas Oce\\xe1nicas y Continentales\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-fisica-2-3-1\",\n                        \"codigo\": \"2.3.1\",\n                        \"titulo\": \"Aguas Oce\\xe1nicas\",\n                        \"descripcion\": \"Propiedades f\\xedsicas (temperatura, densidad) y qu\\xedmicas (salinidad promedio 35 g/L).\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-3-2\",\n                        \"codigo\": \"2.3.2\",\n                        \"titulo\": \"Movimientos del oc\\xe9ano\",\n                        \"descripcion\": \"Corrientes marinas: c\\xe1lidas (ecuador, lluvias, agricultura; ej. Golfo) y fr\\xedas (polos, desiertos costeros, pesca; ej. Humboldt, California). Mareas: flujo/pleamar y reflujo/bajamar por Luna y Sol.\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-3-3\",\n                        \"codigo\": \"2.3.3\",\n                        \"titulo\": \"Aguas Continentales\",\n                        \"descripcion\": \"Distribuci\\xf3n del agua dulce (r\\xedos, lagos, acu\\xedferos, glaciares). Cuenca hidrol\\xf3gica. R\\xedos de M\\xe9xico: Lerma-Santiago, Balsas, Grijalva-Usumacinta (m\\xe1s caudaloso), Bravo. Mundo: Amazonas, Nilo, Misisipi, Yangts\\xe9.\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"geo-fisica-2-4\",\n                \"codigo\": \"2.4\",\n                \"titulo\": \"Atm\\xf3sfera, Climas y Regiones Naturales\",\n                \"orden\": 4,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-fisica-2-4-1\",\n                        \"codigo\": \"2.4.1\",\n                        \"titulo\": \"Capas de la atm\\xf3sfera\",\n                        \"descripcion\": \"Troposfera (fen\\xf3menos meteorol\\xf3gicos), estratosfera (ozono O₃), mesosfera, termosfera/ionosfera (radio, auroras), exosfera.\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-4-2\",\n                        \"codigo\": \"2.4.2\",\n                        \"titulo\": \"Elementos y Factores del Clima\",\n                        \"descripcion\": \"Elementos: temperatura, presi\\xf3n, viento, humedad, precipitaci\\xf3n. Factores: latitud, altitud, relieve, continentalidad, corrientes marinas.\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-4-3\",\n                        \"codigo\": \"2.4.3\",\n                        \"titulo\": \"Clasificaci\\xf3n Clim\\xe1tica de K\\xf6ppen\",\n                        \"descripcion\": \"A: tropicales (>18 \\xb0C). B: secos/esteparios y des\\xe9rticos. C: templados (mes fr\\xedo entre −3 \\xb0C y 18 \\xb0C). D: fr\\xedos. E: polares. Min\\xfasculas: f (lluvias todo el a\\xf1o), w (verano), s (invierno), m (monz\\xf3n). Seco/polar: W, S, T, F. Ejemplos UNAM: Af (selva), Aw (sabana), BS (estepa), BW (desierto), Cf (bosque templado).\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-fisica-2-4-4\",\n                        \"codigo\": \"2.4.4\",\n                        \"titulo\": \"Regiones Naturales\",\n                        \"descripcion\": \"Relaci\\xf3n clima–vegetaci\\xf3n–fauna. Biodiversidad. Pa\\xedses megadiversos (M\\xe9xico, Brasil, Colombia, Australia, Indonesia, etc.).\",\n                        \"orden\": 4,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        \"id\": \"geo-humana\",\n        \"codigo\": \"3\",\n        \"titulo\": \"Geograf\\xeda Humana: Poblaci\\xf3n y Econom\\xeda\",\n        \"orden\": 3,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"geo-humana-3-1\",\n                \"codigo\": \"3.1\",\n                \"titulo\": \"Demograf\\xeda y Din\\xe1mica de la Poblaci\\xf3n Mundial y de M\\xe9xico\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-humana-3-1-1\",\n                        \"codigo\": \"3.1.1\",\n                        \"titulo\": \"Indicadores demogr\\xe1ficos\",\n                        \"descripcion\": \"Poblaci\\xf3n absoluta, densidad relativa (hab/km\\xb2), tasas de natalidad, mortalidad, morbilidad y fecundidad, esperanza de vida.\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-humana-3-1-2\",\n                        \"codigo\": \"3.1.2\",\n                        \"titulo\": \"Distribuci\\xf3n de la poblaci\\xf3n\",\n                        \"descripcion\": \"Pa\\xedses sobrepoblados (India, China, EE. UU., Indonesia, Pakist\\xe1n). Vac\\xedos demogr\\xe1ficos. Focos en M\\xe9xico: Eje Neovolc\\xe1nico, ZMVM, Monterrey, Guadalajara.\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-humana-3-1-3\",\n                        \"codigo\": \"3.1.3\",\n                        \"titulo\": \"Estructura de la poblaci\\xf3n\",\n                        \"descripcion\": \"Pir\\xe1mides progresivas de base ancha (pa\\xedses en desarrollo) vs. regresivas de base estrecha (desarrollados, envejecimiento; Europa occidental, Jap\\xf3n).\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"geo-humana-3-2\",\n                \"codigo\": \"3.2\",\n                \"titulo\": \"Fen\\xf3menos Migratorios\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-humana-3-2-1\",\n                        \"codigo\": \"3.2.1\",\n                        \"titulo\": \"Conceptos\",\n                        \"descripcion\": \"Emigraci\\xf3n (salida del lugar de origen) e inmigraci\\xf3n (llegada al destino).\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-humana-3-2-2\",\n                        \"codigo\": \"3.2.2\",\n                        \"titulo\": \"Causas de la migraci\\xf3n\",\n                        \"descripcion\": \"Econ\\xf3micas (empleo, salarios), pol\\xedticas y sociales (guerras, persecuciones, refugiados), naturales (desastres).\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-humana-3-2-3\",\n                        \"codigo\": \"3.2.3\",\n                        \"titulo\": \"Principales flujos migratorios mundiales\",\n                        \"descripcion\": \"Latinoam\\xe9rica → EE. UU.; \\xc1frica del Norte, Medio Oriente y Europa del Este → Europa occidental; sur y sureste asi\\xe1tico → Golfo P\\xe9rsico. Consecuencias: remesas, fuga de cerebros, multiculturalidad, xenofobia.\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"geo-humana-3-3\",\n                \"codigo\": \"3.3\",\n                \"titulo\": \"Geograf\\xeda Econ\\xf3mica y Globalizaci\\xf3n\",\n                \"orden\": 3,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-humana-3-3-1\",\n                        \"codigo\": \"3.3.1\",\n                        \"titulo\": \"Sectores Econ\\xf3micos\",\n                        \"descripcion\": \"Primario: agricultura, ganader\\xeda, pesca, silvicultura, miner\\xeda (extractiva). Secundario: industria manufacturera, textil, petroqu\\xedmica, metal\\xfargica, construcci\\xf3n. Terciario: comercio, transportes, comunicaciones, turismo, finanzas, salud, educaci\\xf3n.\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-humana-3-3-2\",\n                        \"codigo\": \"3.3.2\",\n                        \"titulo\": \"Globalizaci\\xf3n Econ\\xf3mica y Neoliberalismo\",\n                        \"descripcion\": \"Interconexi\\xf3n mundial; libre flujo de capitales; transnacionalizaci\\xf3n; deslocalizaci\\xf3n industrial hacia mano de obra barata.\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-humana-3-3-3\",\n                        \"codigo\": \"3.3.3\",\n                        \"titulo\": \"Bloques Econ\\xf3micos Regionales\",\n                        \"descripcion\": \"T-MEC (M\\xe9xico, EE. UU., Canad\\xe1), Uni\\xf3n Europea (Euro), MERCOSUR (Brasil, Argentina, Paraguay, Uruguay), APEC (Asia-Pac\\xedfico).\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-humana-3-3-4\",\n                        \"codigo\": \"3.3.4\",\n                        \"titulo\": \"Desigualdad Socioecon\\xf3mica Mundial\",\n                        \"descripcion\": \"Pa\\xedses centrales/desarrollados vs. perif\\xe9ricos/en desarrollo. \\xcdndice de Desarrollo Humano (IDH): esperanza de vida, escolaridad, PIB per c\\xe1pita.\",\n                        \"orden\": 4,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            }\n        ]\n    },\n    {\n        \"id\": \"geo-mexico\",\n        \"codigo\": \"4\",\n        \"titulo\": \"Organizaci\\xf3n Pol\\xedtica y Geograf\\xeda de M\\xe9xico\",\n        \"orden\": 4,\n        \"status\": \"publicado\",\n        \"children\": [\n            {\n                \"id\": \"geo-mexico-4-1\",\n                \"codigo\": \"4.1\",\n                \"titulo\": \"Divisi\\xf3n Pol\\xedtica Mundial y Fronteras\",\n                \"orden\": 1,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-mexico-4-1-1\",\n                        \"codigo\": \"4.1.1\",\n                        \"titulo\": \"Conceptos\",\n                        \"descripcion\": \"Territorio, estado y frontera (natural o artificial). Cambios por desintegraci\\xf3n de URSS, Yugoslavia y Checoslovaquia. Conflictos fronterizos actuales.\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            },\n            {\n                \"id\": \"geo-mexico-4-2\",\n                \"codigo\": \"4.2\",\n                \"titulo\": \"Geograf\\xeda de la Rep\\xfablica Mexicana\",\n                \"orden\": 2,\n                \"status\": \"publicado\",\n                \"children\": [\n                    {\n                        \"id\": \"geo-mexico-4-2-1\",\n                        \"codigo\": \"4.2.1\",\n                        \"titulo\": \"Organizaci\\xf3n Territorial\",\n                        \"descripcion\": \"32 entidades federativas (31 estados y CDMX). Frontera norte con EE. UU. (R\\xedo Bravo); sureste con Guatemala (Suchiate, Usumacinta) y Belice (R\\xedo Hondo).\",\n                        \"orden\": 1,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-mexico-4-2-2\",\n                        \"codigo\": \"4.2.2\",\n                        \"titulo\": \"Principales Sistemas Monta\\xf1osos de M\\xe9xico\",\n                        \"descripcion\": \"Sierra Madre Occidental, Oriental, Eje Neovolc\\xe1nico (Citlalt\\xe9petl, Popocat\\xe9petl, Iztacc\\xedhuatl, Nevado de Toluca, Par\\xedcutin), Sierra Madre del Sur, Sierra Madre de Chiapas.\",\n                        \"orden\": 2,\n                        \"status\": \"publicado\"\n                    },\n                    {\n                        \"id\": \"geo-mexico-4-2-3\",\n                        \"codigo\": \"4.2.3\",\n                        \"titulo\": \"Geograf\\xeda Econ\\xf3mica de M\\xe9xico\",\n                        \"descripcion\": \"Petr\\xf3leo: Golfo y Sonda de Campeche. Miner\\xeda: plata (Zacatecas, Chihuahua, Durango, Sonora). Agricultura comercial en norte/noroeste (Sinaloa, Sonora); subsistencia en sur/sureste. Maquiladora en frontera norte (BC, Chihuahua, Coahuila, Tamaulipas, Nuevo Le\\xf3n).\",\n                        \"orden\": 3,\n                        \"status\": \"publicado\"\n                    }\n                ]\n            }\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/unam-temario-geografia.ts\n");

